          <div className="flex items-center justify-between p-3 rounded-lg bg-[#0b0f17] border border-[#151d28]"><div><div className="text-sm font-medium">Mode Gelap</div><div className="text-xs text-[#6b7688]">Tema default untuk area gudang</div></div><Toggle on={true} onClick={() => toast.info('Mode terang segera hadir')} /></div>
        </div>

        <div className="card-surface p-6">
          <div className="flex items-center gap-2 mb-5"><Database size={18} className="text-[#22c55e]" /><h2 className="font-display text-lg font-bold">Data</h2></div>
          <div className="space-y-3">
            {user?.role === 'Administrator' ? (
              <button data-testid="reset-data-btn" onClick={async () => { if (!window.confirm('Hapus semua transaksi, surat jalan & PO, lalu muat ulang produk & supplier dari data master CSV?')) return; try { await resetData(); toast.success('Data direset — produk & supplier dimuat ulang dari CSV master'); } catch { toast.error('Gagal mereset data'); } }} className="w-full text-left p-3 rounded-lg bg-[#0b0f17] border border-[#151d28] hover:border-[#ef4444] transition-colors text-sm text-[#f87171]">Reset semua transaksi & muat ulang data master dari CSV (31 produk)</button>
            ) : (
              <p className="text-sm text-[#6b7688] p-3">Hanya Administrator yang dapat mereset data.</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Pengaturan;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Printer, Plus, MonitorSmartphone, Truck } from 'lucide-react';
import { useData } from '../context/DataContext';
import { formatNum, formatDate } from '../mock';
import { toast } from 'sonner';

const STATUS = { 'Menunggu': { c: '#eab308', bg: 'rgba(234,179,8,.15)' }, 'Sedang Dimuat': { c: '#3b82f6', bg: 'rgba(59,130,246,.15)' }, 'Selesai': { c: '#22c55e', bg: 'rgba(34,197,94,.15)' } };

const Pengeluaran = () => {
  const { suratJalan, updateSJStatus } = useData();
  const navigate = useNavigate();
  const [filter, setFilter] = useState('Semua Status');
  const [selected, setSelected] = useState([]);

  const list = suratJalan.filter((sj) => filter === 'Semua Status' || sj.status === filter);
  const toggle = (id) => setSelected((s) => (s.includes(id) ? s.filter((x) => x !== id) : [...s, id]));

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <div className="label-mono mb-2">Pengiriman Barang</div>
          <h1 className="font-display text-4xl font-bold">Pengeluaran &amp; Surat Jalan</h1>
          <p className="text-[#8b93a1] mt-2">{suratJalan.length} surat jalan · setiap dokumen bisa memuat beberapa jenis barang</p>
        </div>
        <div className="flex gap-2">
          <button onClick={() => navigate('/antrian')} className="inline-flex items-center gap-2 text-sm font-medium px-4 py-2.5 rounded-lg border border-[#242f3d] hover:bg-[#141a24]"><MonitorSmartphone size={15} /> Layar Antrian</button>
          <button onClick={() => navigate('/catat')} className="btn-primary inline-flex items-center gap-2 text-sm font-semibold px-4 py-2.5 rounded-lg"><Plus size={15} /> Pengeluaran Baru</button>
        </div>
      </div>

      <div className="card-surface p-6">
        <div className="flex flex-wrap items-center justify-between gap-3 mb-4">
          <select data-testid="sj-status-filter" value={filter} onChange={(e) => setFilter(e.target.value)} className="bg-[#0b0f17] border border-[#242f3d] rounded-lg px-3 py-2.5 text-sm outline-none"><option>Semua Status</option><option>Menunggu</option><option>Sedang Dimuat</option><option>Selesai</option></select>
          <button onClick={() => { toast.success(`Mencetak ${selected.length} surat jalan (mock)`); }} className="inline-flex items-center gap-2 text-sm font-medium px-4 py-2.5 rounded-lg border border-[#242f3d] hover:bg-[#141a24]"><Printer size={15} /> Cetak Surat Jalan ({selected.length}) — A4</button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-sm tbl">
            <thead><tr className="text-left border-b border-[#1a222e]">{['', 'No. Surat Jalan', 'Antrian', 'Waktu', 'Penerima', 'Barang', 'Total Berat', 'Total Unit', 'Status', 'Aksi'].map((h, i) => <th key={i} className="py-2.5 pr-4 font-semibold whitespace-nowrap">{h}</th>)}</tr></thead>
            <tbody>
              {list.length === 0 ? <tr><td colSpan={10} className="py-8 text-center text-[#6b7688]">Belum ada surat jalan. Buat pengeluaran baru.</td></tr> : list.map((sj) => (
                <tr key={sj.id} className="tbl-row border-b border-[#131a24] align-top">
                  <td className="py-3 pr-4"><input type="checkbox" checked={selected.includes(sj.id)} onChange={() => toggle(sj.id)} className="accent-[#2563eb] w-4 h-4" /></td>
                  <td className="py-3 pr-4 font-mono text-xs">{sj.no}</td>
                  <td className="py-3 pr-4 font-mono text-xs">{sj.antrian}</td>
                  <td className="py-3 pr-4 whitespace-nowrap text-[#8b93a1]">{formatDate(sj.time)}</td>
                  <td className="py-3 pr-4 text-[#c7d0dc]">{sj.penerima}</td>
                  <td className="py-3 pr-4 text-xs max-w-xs">{sj.items.map((it, i) => <div key={i} className="text-[#aab4c4]">{it.name} × {it.berat} Kg <span className="text-[#6b7688]">({formatNum(it.qty)} {it.unit})</span></div>)}</td>
                  <td className="py-3 pr-4 font-mono whitespace-nowrap">{formatNum(sj.berat)} kg</td>
                  <td className="py-3 pr-4 font-mono">{formatNum(sj.unit)}</td>
                  <td className="py-3 pr-4"><span className="text-xs px-2.5 py-1 rounded-full font-medium whitespace-nowrap" style={{ background: STATUS[sj.status]?.bg, color: STATUS[sj.status]?.c }}>{sj.status}</span></td>
                  <td className="py-3 pr-4">
                    {sj.status === 'Menunggu' && <button data-testid={`sj-mulai-muat-btn-${sj.no}`} onClick={() => { updateSJStatus(sj.id, 'Sedang Dimuat'); toast.success('Mulai memuat'); }} className="text-xs font-semibold px-3 py-1.5 rounded-lg border border-[#2563eb] text-[#60a5fa] hover:bg-[#2563eb]/10 whitespace-nowrap">Mulai Muat</button>}
                    {sj.status === 'Sedang Dimuat' && <button data-testid={`sj-selesai-btn-${sj.no}`} onClick={() => { updateSJStatus(sj.id, 'Selesai'); toast.success('Pemuatan selesai'); }} className="btn-primary text-xs font-semibold px-3 py-1.5 rounded-lg whitespace-nowrap">Selesai</button>}
                    {sj.status === 'Selesai' && <span className="text-xs text-[#6b7688]">—</span>}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Pengeluaran;

import React, { useState } from 'react';
import { Plus, X, ShieldCheck, User as UserIcon, KeyRound, Trash2, Power } from 'lucide-react';
import { useData } from '../context/DataContext';
import { apiError } from '../lib/api';
import { toast } from 'sonner';

const ROLE_COLOR = { 'Administrator': '#ef4444', 'Supervisor': '#a855f7', 'Operator': '#3b82f6', 'Pemantau': '#8b93a1' };
const ROLES = ['Administrator', 'Supervisor', 'Operator', 'Pemantau'];

const inputCls = 'w-full bg-[#0b0f17] border border-[#242f3d] rounded-lg px-3 py-2.5 text-sm outline-none focus:border-[#2563eb]';

const Modal = ({ title, onClose, children }) => (
  <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 pt-20" onClick={onClose}>
    <div className="card-surface w-full max-w-md p-6 fade-up max-h-[90vh] overflow-y-auto" onClick={(e) => e.stopPropagation()}>
      <div className="flex items-center justify-between mb-5">
        <h2 className="font-display text-xl font-bold">{title}</h2>
        <button data-testid="modal-close-btn" onClick={onClose} className="text-[#8b93a1] hover:text-white"><X size={20} /></button>
      </div>
      {children}
    </div>
  </div>
);

const Pengguna = () => {
  const { user, users, addUser, deleteUser, updateUser, changeUserPassword } = useData();
  const isAdmin = user?.role === 'Administrator';
  const [modal, setModal] = useState(false);
  const [form, setForm] = useState({ name: '', username: '', email: '', role: 'Operator', password: '' });
  const [pwdModal, setPwdModal] = useState(null);
  const [newPwd, setNewPwd] = useState('');
  const [delModal, setDelModal] = useState(null);

  const save = async () => {
    if (!form.name || !form.username || !form.password) { toast.error('Nama, username & password wajib diisi'); return; }
    try {
      await addUser(form);
      toast.success('Pengguna ditambahkan');
      setModal(false);
      setForm({ name: '', username: '', email: '', role: 'Operator', password: '' });
    } catch (e) { toast.error(apiError(e)); }
  };

  const savePwd = async () => {
    if (newPwd.length < 6) { toast.error('Password minimal 6 karakter'); return; }
    try {
      await changeUserPassword(pwdModal.id, newPwd);
      toast.success(`Password ${pwdModal.name} diganti`);
      setPwdModal(null); setNewPwd('');
    } catch (e) { toast.error(apiError(e)); }
  };

  const confirmDelete = async () => {
    try {
      await deleteUser(delModal.id);
      toast.success(`Pengguna ${delModal.name} dihapus`);
      setDelModal(null);
    } catch (e) { toast.error(apiError(e)); }
  };

  const toggleActive = async (u) => {
    try {
      await updateUser(u.id, { active: !u.active });
      toast.success(u.active ? `${u.name} dinonaktifkan` : `${u.name} diaktifkan`);
    } catch (e) { toast.error(apiError(e)); }
  };

  const changeRole = async (u, role) => {
    try {
      await updateUser(u.id, { role });
      toast.success(`Peran ${u.name} diubah menjadi ${role}`);
    } catch (e) { toast.error(apiError(e)); }
  };

  return (
    <div className="space-y-6" data-testid="pengguna-page">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <div className="label-mono mb-2">Kontrol Akses</div>
          <h1 className="font-display text-4xl font-bold">Pengguna</h1>
          <p className="text-[#8b93a1] mt-2">{users.length} akun terdaftar · {isAdmin ? 'kelola akun, peran & password' : 'hanya Administrator yang dapat mengelola akun'}</p>
        </div>
        {isAdmin && (
          <button data-testid="add-user-btn" onClick={() => setModal(true)} className="btn-primary inline-flex items-center gap-2 text-sm font-semibold px-4 py-2.5 rounded-lg"><Plus size={15} /> Tambah Pengguna</button>
        )}
      </div>

      <div className="card-surface p-6">
        <div className="overflow-x-auto">
          <table className="w-full text-sm tbl">
            <thead><tr className="text-left border-b border-[#1a222e]">{['Nama', 'Username', 'Email', 'Peran', 'Status', isAdmin ? 'Aksi' : ''].filter(Boolean).map((h) => <th key={h} className="py-2.5 pr-4 font-semibold">{h}</th>)}</tr></thead>
            <tbody>
              {users.map((u) => (
                <tr key={u.id} data-testid={`user-row-${u.username}`} className="tbl-row border-b border-[#131a24]">
                  <td className="py-3 pr-4"><div className="flex items-center gap-3"><div className="w-9 h-9 rounded-full bg-[#1a222e] flex items-center justify-center text-[#60a5fa]"><UserIcon size={16} /></div><span className="font-medium">{u.name}{u.id === user?.id && <span className="text-[10px] text-[#60a5fa] ml-2">(Anda)</span>}</span></div></td>
                  <td className="py-3 pr-4 font-mono text-xs text-[#8b93a1]">{u.username}</td>
                  <td className="py-3 pr-4 text-[#aab4c4]">{u.email || '—'}</td>
                  <td className="py-3 pr-4">
                    {isAdmin && u.id !== user?.id ? (
                      <select data-testid={`role-select-${u.username}`} value={u.role} onChange={(e) => changeRole(u, e.target.value)} className="bg-[#0b0f17] border border-[#242f3d] rounded-lg px-2 py-1.5 text-xs outline-none focus:border-[#2563eb]" style={{ color: ROLE_COLOR[u.role] }}>
                        {ROLES.map((r) => <option key={r}>{r}</option>)}
                      </select>
                    ) : (
                      <span className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full font-medium" style={{ background: `${ROLE_COLOR[u.role]}22`, color: ROLE_COLOR[u.role] }}><ShieldCheck size={12} /> {u.role}</span>
                    )}
                  </td>
                  <td className="py-3 pr-4"><span className={`text-xs px-2.5 py-1 rounded-full ${u.active ? 'bg-[#22c55e]/15 text-[#22c55e]' : 'bg-[#6b7688]/15 text-[#8b93a1]'}`}>{u.active ? 'Aktif' : 'Nonaktif'}</span></td>
                  {isAdmin && (
                    <td className="py-3 pr-4">
                      <div className="flex items-center gap-1.5">
                        <button data-testid={`change-pwd-btn-${u.username}`} title="Ganti password" onClick={() => { setPwdModal(u); setNewPwd(''); }} className="w-8 h-8 rounded-lg border border-[#242f3d] flex items-center justify-center text-[#eab308] hover:bg-[#eab308]/10"><KeyRound size={14} /></button>
                        {u.id !== user?.id && (
                          <>
                            <button data-testid={`toggle-active-btn-${u.username}`} title={u.active ? 'Nonaktifkan' : 'Aktifkan'} onClick={() => toggleActive(u)} className={`w-8 h-8 rounded-lg border border-[#242f3d] flex items-center justify-center ${u.active ? 'text-[#8b93a1]' : 'text-[#22c55e]'} hover:bg-[#141a24]`}><Power size={14} /></button>
                            <button data-testid={`delete-user-btn-${u.username}`} title="Hapus pengguna" onClick={() => setDelModal(u)} className="w-8 h-8 rounded-lg border border-[#242f3d] flex items-center justify-center text-[#ef4444] hover:bg-[#ef4444]/10"><Trash2 size={14} /></button>
                          </>
                        )}
                      </div>
                    </td>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {modal && (
        <Modal title="Tambah Pengguna" onClose={() => setModal(false)}>
          <div className="space-y-4">
            {[['name', 'Nama Lengkap'], ['username', 'Username'], ['email', 'Email (opsional)']].map(([k, l]) => (
              <div key={k}><label className="text-xs font-medium mb-1 block text-[#8b93a1]">{l}</label><input data-testid={`user-form-${k}`} value={form[k]} onChange={(e) => setForm({ ...form, [k]: e.target.value })} className={inputCls} /></div>
            ))}
            <div><label className="text-xs font-medium mb-1 block text-[#8b93a1]">Password (min. 6 karakter)</label><input data-testid="user-form-password" type="password" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} className={inputCls} /></div>
            <div><label className="text-xs font-medium mb-1 block text-[#8b93a1]">Peran</label><select data-testid="user-form-role" value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value })} className={inputCls}>{ROLES.map((r) => <option key={r}>{r}</option>)}</select></div>
          </div>
          <div className="flex justify-end gap-2 mt-6">
            <button onClick={() => setModal(false)} className="px-4 py-2.5 rounded-lg border border-[#242f3d] text-sm hover:bg-[#141a24]">Batal</button>
            <button data-testid="user-form-submit" onClick={save} className="btn-primary px-5 py-2.5 rounded-lg text-sm font-semibold">Simpan</button>
          </div>
        </Modal>
      )}

      {pwdModal && (
        <Modal title={`Ganti Password — ${pwdModal.name}`} onClose={() => setPwdModal(null)}>
          <div><label className="text-xs font-medium mb-1 block text-[#8b93a1]">Password Baru (min. 6 karakter)</label><input data-testid="new-password-input" type="password" value={newPwd} onChange={(e) => setNewPwd(e.target.value)} className={inputCls} autoFocus /></div>
          <div className="flex justify-end gap-2 mt-6">
            <button onClick={() => setPwdModal(null)} className="px-4 py-2.5 rounded-lg border border-[#242f3d] text-sm hover:bg-[#141a24]">Batal</button>
            <button data-testid="save-password-btn" onClick={savePwd} className="btn-primary px-5 py-2.5 rounded-lg text-sm font-semibold">Ganti Password</button>
          </div>
        </Modal>
      )}

      {delModal && (
        <Modal title="Hapus Pengguna" onClose={() => setDelModal(null)}>
          <p className="text-sm text-[#aab4c4]">Yakin ingin menghapus akun <span className="font-semibold text-white">{delModal.name}</span> (<span className="font-mono text-xs">{delModal.username}</span>)? Tindakan ini tidak dapat dibatalkan.</p>
          <div className="flex justify-end gap-2 mt-6">
            <button onClick={() => setDelModal(null)} className="px-4 py-2.5 rounded-lg border border-[#242f3d] text-sm hover:bg-[#141a24]">Batal</button>
            <button data-testid="confirm-delete-user-btn" onClick={confirmDelete} className="px-5 py-2.5 rounded-lg text-sm font-semibold bg-[#ef4444] hover:bg-[#dc2626] text-white">Hapus</button>
          </div>
        </Modal>
      )}
    </div>
  );
};

export default Pengguna;

import React, { useState } from 'react';
import { Plus, X } from 'lucide-react';
import { useData } from '../context/DataContext';
import { formatRp, formatDate, formatNum } from '../mock';
import { toast } from 'sonner';

const STATUS = { 'Draft': '#8b93a1', 'Menunggu': '#eab308', 'Dikirim': '#3b82f6', 'Diterima': '#22c55e' };

const PurchaseOrder = () => {
  const { purchaseOrders, suppliers, products, addPO } = useData();
  const [modal, setModal] = useState(false);
  const [form, setForm] = useState({ supplier: '', productId: '', qty: 1 });

  const save = async () => {
    const prod = products.find((p) => p.id === form.productId);
    if (!form.supplier || !prod) { toast.error('Lengkapi supplier & produk'); return; }
    try {
      await addPO({ supplier: form.supplier, date: new Date().toISOString(), status: 'Draft', items: [{ name: prod.name, qty: Number(form.qty), cost: prod.cost }], total: prod.cost * Number(form.qty) });
      toast.success('Purchase Order dibuat'); setModal(false); setForm({ supplier: '', productId: '', qty: 1 });
    } catch { toast.error('Gagal membuat PO'); }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <div className="label-mono mb-2">Pengadaan</div>
          <h1 className="font-display text-4xl font-bold">Purchase Order</h1>
          <p className="text-[#8b93a1] mt-2">{purchaseOrders.length} PO tercatat</p>
        </div>
        <button data-testid="create-po-btn" onClick={() => setModal(true)} className="btn-primary inline-flex items-center gap-2 text-sm font-semibold px-4 py-2.5 rounded-lg"><Plus size={15} /> Buat PO Baru</button>
      </div>

      <div className="card-surface p-6">
        <div className="overflow-x-auto">
          <table className="w-full text-sm tbl">
            <thead><tr className="text-left border-b border-[#1a222e]">{['No. PO', 'Tanggal', 'Supplier', 'Barang', 'Total Nilai', 'Status'].map((h) => <th key={h} className="py-2.5 pr-4 font-semibold whitespace-nowrap">{h}</th>)}</tr></thead>
            <tbody>
              {purchaseOrders.length === 0 ? <tr><td colSpan={6} className="py-8 text-center text-[#6b7688]">Belum ada PO. Buat PO baru.</td></tr> : purchaseOrders.map((po) => (
                <tr key={po.id} className="tbl-row border-b border-[#131a24]">
                  <td className="py-3 pr-4 font-mono text-xs">{po.no}</td>
                  <td className="py-3 pr-4 whitespace-nowrap text-[#8b93a1]">{formatDate(po.date)}</td>
                  <td className="py-3 pr-4 text-[#c7d0dc]">{po.supplier}</td>
                  <td className="py-3 pr-4 text-xs">{po.items.map((it, i) => <div key={i}>{it.name} × {formatNum(it.qty)}</div>)}</td>
                  <td className="py-3 pr-4 font-mono">{formatRp(po.total)}</td>
                  <td className="py-3 pr-4"><span className="text-xs px-2.5 py-1 rounded-full font-medium" style={{ background: `${STATUS[po.status]}22`, color: STATUS[po.status] }}>{po.status}</span></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {modal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4" onClick={() => setModal(false)}>
          <div className="card-surface w-full max-w-md p-6 fade-up" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-5"><h2 className="font-display text-xl font-bold">Buat Purchase Order</h2><button onClick={() => setModal(false)} className="text-[#8b93a1] hover:text-white"><X size={20} /></button></div>
            <div className="space-y-4">
              <div><label className="text-xs font-medium mb-1 block text-[#8b93a1]">Supplier</label><select data-testid="po-supplier-select" value={form.supplier} onChange={(e) => setForm({ ...form, supplier: e.target.value })} className="w-full bg-[#0b0f17] border border-[#242f3d] rounded-lg px-3 py-2.5 text-sm outline-none focus:border-[#2563eb]"><option value="">Pilih supplier...</option>{suppliers.map((s) => <option key={s.id}>{s.name}</option>)}</select></div>
              <div><label className="text-xs font-medium mb-1 block text-[#8b93a1]">Produk</label><select data-testid="po-product-select" value={form.productId} onChange={(e) => setForm({ ...form, productId: e.target.value })} className="w-full bg-[#0b0f17] border border-[#242f3d] rounded-lg px-3 py-2.5 text-sm outline-none focus:border-[#2563eb]"><option value="">Pilih produk...</option>{products.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}</select></div>
              <div><label className="text-xs font-medium mb-1 block text-[#8b93a1]">Jumlah Pesan</label><input data-testid="po-qty-input" type="number" min="1" value={form.qty} onChange={(e) => setForm({ ...form, qty: e.target.value })} className="w-full bg-[#0b0f17] border border-[#242f3d] rounded-lg px-3 py-2.5 text-sm outline-none focus:border-[#2563eb]" /></div>
            </div>
            <div className="flex justify-end gap-2 mt-6"><button onClick={() => setModal(false)} className="px-4 py-2.5 rounded-lg border border-[#242f3d] text-sm hover:bg-[#141a24]">Batal</button><button data-testid="po-save-btn" onClick={save} className="btn-primary px-5 py-2.5 rounded-lg text-sm font-semibold">Simpan PO</button></div>
          </div>
        </div>
      )}
    </div>
  );
};

export default PurchaseOrder;

import React, { useState } from 'react';
import { Search, Download, Printer } from 'lucide-react';
import { useData } from '../context/DataContext';
import { formatNum, formatDate } from '../mock';
import { toast } from 'sonner';

const Riwayat = () => {
  const { transactions } = useData();
  const [q, setQ] = useState('');
  const [type, setType] = useState('SEMUA');
  const [kondisi, setKondisi] = useState('SEMUA');

  const filtered = transactions.filter((t) => (type === 'SEMUA' || t.type === type) && (kondisi === 'SEMUA' || t.kondisi === kondisi) && (t.ref?.toLowerCase().includes(q.toLowerCase()) || t.product.toLowerCase().includes(q.toLowerCase()) || t.sku.toLowerCase().includes(q.toLowerCase()) || (t.penerima || '').toLowerCase().includes(q.toLowerCase())));
  const totalIn = transactions.filter((t) => t.type === 'MASUK').reduce((a, t) => a + t.change, 0);
  const totalOut = transactions.filter((t) => t.type === 'KELUAR').reduce((a, t) => a + t.change, 0);

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <div className="label-mono mb-2">Audit Trail</div>
          <h1 className="font-display text-4xl font-bold">Riwayat Transaksi Stok</h1>
          <p className="text-[#8b93a1] mt-2">{filtered.length} transaksi ditampilkan</p>
        </div>
        <div className="flex gap-3">
          <div className="card-surface px-5 py-3"><div className="label-mono text-[9px] mb-1">Total Masuk</div><div className="font-mono text-2xl font-bold text-[#22c55e]">+{formatNum(totalIn)}</div></div>
          <div className="card-surface px-5 py-3"><div className="label-mono text-[9px] mb-1">Total Keluar</div><div className="font-mono text-2xl font-bold text-[#ef4444]">{formatNum(totalOut)}</div></div>
        </div>
      </div>

      <div className="card-surface p-6">
        <div className="flex flex-wrap gap-3 mb-4">
          <div className="relative flex-1 min-w-[240px]"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#6b7688]" /><input data-testid="riwayat-search-input" value={q} onChange={(e) => setQ(e.target.value)} placeholder="Cari No. Ref, produk, SKU, pihak terkait..." className="w-full bg-[#0b0f17] border border-[#242f3d] rounded-lg pl-9 pr-3 py-2.5 text-sm outline-none focus:border-[#2563eb]" /></div>
          <select data-testid="riwayat-type-filter" value={type} onChange={(e) => setType(e.target.value)} className="bg-[#0b0f17] border border-[#242f3d] rounded-lg px-3 py-2.5 text-sm outline-none"><option value="SEMUA">SEMUA</option><option value="MASUK">MASUK</option><option value="KELUAR">KELUAR</option></select>
          <select data-testid="riwayat-kondisi-filter" value={kondisi} onChange={(e) => setKondisi(e.target.value)} className="bg-[#0b0f17] border border-[#242f3d] rounded-lg px-3 py-2.5 text-sm outline-none"><option value="SEMUA">SEMUA</option><option value="BAIK">BAIK</option><option value="RUSAK">RUSAK</option></select>
          <button onClick={() => toast.success('Excel bulan ini diunduh (mock)')} className="inline-flex items-center gap-2 text-sm font-medium px-4 py-2.5 rounded-lg border border-[#242f3d] hover:bg-[#141a24]"><Download size={15} /> Unduh Excel Bulan Ini</button>
        </div>
        <p className="text-xs text-[#6b7688] mb-4">Cetak surat jalan & bon muat ada di halaman Pengeluaran.</p>

        <div className="overflow-x-auto">
          <table className="w-full text-sm tbl">
            <thead><tr className="text-left border-b border-[#1a222e]">{['Waktu', 'No. Referensi', 'Antrian', 'Tipe', 'Kondisi', 'Produk', 'Perubahan', 'Pihak Terkait', 'Dicatat Oleh'].map((h) => <th key={h} className="py-2.5 pr-4 font-semibold whitespace-nowrap">{h}</th>)}</tr></thead>
            <tbody>
              {filtered.length === 0 ? <tr><td colSpan={9} className="py-8 text-center text-[#6b7688]">Belum ada transaksi. Muat data contoh atau catat transaksi baru.</td></tr> : filtered.map((t) => (
                <tr key={t.id} className="tbl-row border-b border-[#131a24]">
                  <td className="py-3 pr-4 whitespace-nowrap text-[#8b93a1]">{formatDate(t.time)}</td>
                  <td className="py-3 pr-4 font-mono text-xs">{t.ref}</td>
                  <td className="py-3 pr-4 font-mono text-xs">{t.antrian || '—'}</td>
                  <td className="py-3 pr-4"><span className="text-[10px] font-mono px-2 py-0.5 rounded" style={{ background: t.type === 'MASUK' ? 'rgba(34,197,94,.15)' : 'rgba(239,68,68,.15)', color: t.type === 'MASUK' ? '#22c55e' : '#ef4444' }}>{t.type}</span></td>
                  <td className="py-3 pr-4"><span className="text-[10px] font-mono px-2 py-0.5 rounded bg-[#1a222e] text-[#8b93a1]">{t.kondisi}</span></td>
                  <td className="py-3 pr-4"><div className="font-medium">{t.product}</div><div className="label-mono text-[10px]">{t.sku}</div></td>
                  <td className={`py-3 pr-4 font-mono font-semibold ${t.change > 0 ? 'text-[#22c55e]' : 'text-[#ef4444]'}`}>{t.change > 0 ? '+' : ''}{t.change}</td>
                  <td className="py-3 pr-4 text-[#c7d0dc]">{t.penerima}</td>
                  <td className="py-3 pr-4 text-[#8b93a1] text-xs">{t.operator}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Riwayat;

import React, { useState } from 'react';
import { Plus, X, Phone, Mail, MapPin, User } from 'lucide-react';
import { useData } from '../context/DataContext';
import { catColor, formatNum } from '../mock';
import { toast } from 'sonner';

const Supplier = () => {
  const { suppliers, products, addSupplier } = useData();
  const [modal, setModal] = useState(false);
  const [form, setForm] = useState({ name: '', pic: '', phone: '', email: '', address: '', category: 'Beras' });

  const save = async () => {
    if (!form.name) { toast.error('Nama supplier wajib diisi'); return; }
    try {
      await addSupplier(form); toast.success('Supplier ditambahkan'); setModal(false); setForm({ name: '', pic: '', phone: '', email: '', address: '', category: 'Beras' });
    } catch { toast.error('Gagal menambah supplier'); }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <div className="label-mono mb-2">Mitra Gudang</div>
          <h1 className="font-display text-4xl font-bold">Supplier</h1>
          <p className="text-[#8b93a1] mt-2">{suppliers.length} supplier terdaftar</p>
        </div>
        <button data-testid="add-supplier-btn" onClick={() => setModal(true)} className="btn-primary inline-flex items-center gap-2 text-sm font-semibold px-4 py-2.5 rounded-lg"><Plus size={15} /> Tambah Supplier</button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
        {suppliers.map((s) => {
          const count = products.filter((p) => p.supplier === s.name).length;
          return (
            <div key={s.id} className="card-surface stat-card p-5">
              <div className="flex items-start justify-between mb-3">
                <div className="font-display font-bold text-lg pr-2">{s.name}</div>
                <span className="text-[10px] px-2 py-0.5 rounded-full whitespace-nowrap" style={{ background: `${catColor(s.category)}1f`, color: catColor(s.category) }}>{s.category}</span>
              </div>
              <div className="space-y-2 text-sm text-[#aab4c4]">
                <div className="flex items-center gap-2"><User size={14} className="text-[#6b7688]" /> {s.pic}</div>
                <div className="flex items-center gap-2"><Phone size={14} className="text-[#6b7688]" /> {s.phone}</div>
                <div className="flex items-center gap-2"><Mail size={14} className="text-[#6b7688]" /> {s.email}</div>
                <div className="flex items-start gap-2"><MapPin size={14} className="text-[#6b7688] mt-0.5" /> {s.address}</div>
              </div>
              <div className="mt-4 pt-4 border-t border-[#151d28] flex justify-between text-xs"><span className="text-[#8b93a1]">Produk disuplai</span><span className="font-mono font-semibold text-[#60a5fa]">{formatNum(count)} SKU</span></div>
            </div>
          );
        })}
      </div>

      {modal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4" onClick={() => setModal(false)}>
          <div className="card-surface w-full max-w-md p-6 fade-up" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-5"><h2 className="font-display text-xl font-bold">Tambah Supplier</h2><button onClick={() => setModal(false)} className="text-[#8b93a1] hover:text-white"><X size={20} /></button></div>
            <div className="space-y-4">
              {[['name', 'Nama Supplier'], ['pic', 'PIC / Narahubung'], ['phone', 'Telepon'], ['email', 'Email'], ['address', 'Alamat']].map(([k, l]) => (
                <div key={k}><label className="text-xs font-medium mb-1 block text-[#8b93a1]">{l}</label><input data-testid={`supplier-form-${k}`} value={form[k]} onChange={(e) => setForm({ ...form, [k]: e.target.value })} className="w-full bg-[#0b0f17] border border-[#242f3d] rounded-lg px-3 py-2.5 text-sm outline-none focus:border-[#2563eb]" /></div>
              ))}
            </div>
            <div className="flex justify-end gap-2 mt-6"><button onClick={() => setModal(false)} className="px-4 py-2.5 rounded-lg border border-[#242f3d] text-sm hover:bg-[#141a24]">Batal</button><button data-testid="supplier-save-btn" onClick={save} className="btn-primary px-5 py-2.5 rounded-lg text-sm font-semibold">Simpan</button></div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Supplier;

import React from 'react';
import { useData } from '../context/DataContext';
import { catColor, formatNum, formatRp } from '../mock';

const TumpukanStok = () => {
  const { products } = useData();
  // Group by location zone (first char / rak)
  const zones = {};
  products.forEach((p) => { const zone = p.location.split(' ')[0] === 'Rak' ? p.location.split('-')[0].trim() : p.location; (zones[zone] = zones[zone] || []).push(p); });

  return (
    <div className="space-y-6">
      <div>
        <div className="label-mono mb-2">Tata Letak Gudang</div>
        <h1 className="font-display text-4xl font-bold">Tumpukan Stok per Lokasi</h1>
        <p className="text-[#8b93a1] mt-2">Visualisasi sebaran barang berdasarkan rak & zona penyimpanan</p>
      </div>

      {Object.keys(zones).length === 0 ? (
        <div className="card-surface p-8 text-center text-[#6b7688]">Belum ada produk terdaftar. Muat data contoh untuk melihat tata letak.</div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
          {Object.entries(zones).sort().map(([zone, items]) => {
            const totalUnits = items.reduce((a, p) => a + p.stock, 0);
            return (
              <div key={zone} className="card-surface stat-card p-5">
                <div className="flex items-center justify-between mb-4">
                  <div className="font-display font-bold text-lg">{zone}</div>
                  <span className="label-mono text-[9px]">{formatNum(totalUnits)} unit</span>
                </div>
                <div className="space-y-2">
                  {items.map((p) => (
                    <div key={p.id} className="p-3 rounded-lg bg-[#0b0f17] border border-[#151d28]">
                      <div className="flex items-center justify-between">
                        <span className="text-sm font-medium truncate pr-2">{p.name}</span>
                        <span className="w-2.5 h-2.5 rounded-full shrink-0" style={{ background: catColor(p.category) }} />
                      </div>
                      <div className="flex items-center justify-between mt-1.5">
                        <span className="label-mono text-[9px]">{p.location}</span>
                        <span className="font-mono text-xs text-[#aab4c4]">{formatNum(p.stock)} {p.unit}</span>
                      </div>
                      <div className="h-1.5 rounded-full bg-[#151d28] mt-2 overflow-hidden"><div className="h-full rounded-full" style={{ width: `${Math.min((p.stock / (p.min * 4 || 100)) * 100, 100)}%`, background: catColor(p.category) }} /></div>
                    </div>
                  ))}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default TumpukanStok;

